import sys


def transform(grid):
    """Compress a grid into 3x3 tiles, retaining any symbol other than 0 or 5."""
    h, w = len(grid), len(grid[0])
    out = []
    for r in range(0, h, 3):
        row = []
        for c in range(0, w, 3):
            colors = {grid[i][j] for i in range(r, min(r + 3, h))
                      for j in range(c, min(c + 3, w)) if grid[i][j] not in (0, 5)}
            if len(colors) > 1:
                raise ValueError(f"multiple marker colors in tile ({r // 3}, {c // 3}): {colors}")
            row.append(next(iter(colors)) if colors else 0)
        out.append(row)
    return out


if __name__ == "__main__":
    print(json.dumps(transform(json.load(sys.stdin))))
